#!/usr/bin/env python3
"""An independent, standard-library-only Solidity front end and CLI."""
from __future__ import annotations
import sys, os, re, json, difflib, bisect, math
from dataclasses import dataclass, field
from help_text import SHORT_HELP, LONG_HELP, UNSTABLE_HELP, SHORT_VERSION, LONG_VERSION

# Keccak-f[1600], with the original Keccak padding used for ABI selectors.
_RC = (1,0x8082,0x800000000000808a,0x8000000080008000,0x808b,0x80000001,
       0x8000000080008081,0x8000000000008009,0x8a,0x88,0x80008009,0x8000000a,
       0x8000808b,0x800000000000008b,0x8000000000008089,0x8000000000008003,
       0x8000000000008002,0x8000000000000080,0x800a,0x800000008000000a,
       0x8000000080008081,0x8000000000008080,0x80000001,0x8000000080008008)
_ROT = ((0,36,3,41,18),(1,44,10,45,2),(62,6,43,15,61),(28,55,25,21,56),(27,20,39,8,14))
def keccak(data):
    mask=(1<<64)-1
    def rol(v,n): return ((v<<n)|(v>>(64-n if n else 64)))&mask
    a=[0]*25
    data=bytearray(data); data.append(1)
    data.extend(b'\0'*((135-len(data))%136)); data.append(128)
    for off in range(0,len(data),136):
        for j in range(17): a[j]^=int.from_bytes(data[off+8*j:off+8*j+8],'little')
        for rc in _RC:
            c=[a[x]^a[x+5]^a[x+10]^a[x+15]^a[x+20] for x in range(5)]
            d=[c[(x-1)%5]^rol(c[(x+1)%5],1) for x in range(5)]
            for y in range(5):
                for x in range(5): a[x+5*y]^=d[x]
            b=[0]*25
            for y in range(5):
                for x in range(5): b[y+5*((2*x+3*y)%5)]=rol(a[x+5*y],_ROT[x][y])
            for y in range(5):
                for x in range(5): a[x+5*y]=b[x+5*y]^((~b[(x+1)%5+5*y])&b[(x+2)%5+5*y])
            a[0]^=rc
    return b''.join(x.to_bytes(8,'little') for x in a)[:32]

@dataclass
class Options:
    inputs: list=field(default_factory=list)
    emit: list=field(default_factory=list)
