    includes: list=field(default_factory=list)
    allows: list=field(default_factory=list)
    out: str|None=None
    stop: str|None=None
    evm: str='prague'
    color: str='auto'
    error_format: str='human'
    style: str='unicode'
    width: int=140
    pretty: bool=False
    pretty_err: bool=False
    no_warnings: bool=False
    verbose: bool=False
    threads: int=8
    unstable: list=field(default_factory=list)

_VALUES={
    '--threads':('threads','THREADS',None), '--evm-version':('evm','EVM_VERSION',['homestead','tangerineWhistle','spuriousDragon','byzantium','constantinople','petersburg','istanbul','berlin','london','paris','shanghai','cancun','prague','osaka']),
    '--stop-after':('stop','STOP_AFTER',['parsing','lowering','analysis']),
    '--out-dir':('out','OUT_DIR',None), '--emit':('emit','EMIT',['abi','hashes']),
    '--base-path':('base','BASE_PATH',None), '--include-path':('includes','INCLUDE_PATH',None),
    '--allow-paths':('allows','ALLOW_PATHS',None), '--color':('color','COLOR',['auto','always','never']),
    '--error-format':('error_format','ERROR_FORMAT',['human','json','rustc-json']),
    '--error-format-human':('style','VALUE',['ascii','unicode','short']),
    '--diagnostic-width':('width','WIDTH',None), '-Z':('unstable','FLAG',None)
}
_SWITCHES={'--pretty-json':'pretty','--pretty-json-err':'pretty_err','--no-warnings':'no_warnings','--verbose':'verbose','-v':'verbose'}
def cli_fail(msg,usage=False,tip=None,unstable=False):
    if unstable:
        text="error:  "+msg+"\n"
        if usage: text+='\nUsage: solar [OPTIONS]\n'
        text+="\nFor more information, try '-Zhelp'.\n\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n"
    else:
        text='error: '+msg+'\n'
        if tip: text+='\n  tip: '+tip+'\n'
        if usage: text+='\nUsage: executable [OPTIONS] [INPUT]...\n'
        text+="\nFor more information, try '--help'.\n"
    sys.stderr.write(text); raise SystemExit(2)
def parse_cli(args):
    o=Options(); seen=set(); i=0; literal=False
    if not args: sys.stderr.write(SHORT_HELP+'\n'); raise SystemExit(2)
    while i<len(args):
        a=args[i]; i+=1
        if literal: o.inputs.append(a); continue
        if a=='--':literal=True;continue
        if a in ['-h','--help']:sys.stdout.write(SHORT_HELP if a=='-h' else LONG_HELP);raise SystemExit(0)
        if a in ['-V','--version']:sys.stdout.write(SHORT_VERSION if a=='-V' else LONG_VERSION);raise SystemExit(0)
        if a in _SWITCHES:
            if a in seen:cli_fail(f"the argument '{a}' cannot be used multiple times",True)
            seen.add(a);setattr(o,_SWITCHES[a],True);continue
        if not a.startswith('-') or a=='-':o.inputs.append(a);continue
        val=None
        if a.startswith('--') and '=' in a:a,val=a.split('=',1)
        elif a.startswith('-Z') and a!='-Z':a,val='-Z',a[2:]
        elif a.startswith('-j') and a!='-j':a,val='-j',a[2:]
        elif a.startswith('-I') and a!='-I':a,val='-I',a[2:]
        a={'--jobs':'--threads','-j':'--threads','-I':'--include-path'}.get(a,a)
        if a not in _VALUES:
            close=difflib.get_close_matches(a,list(_VALUES)+list(_SWITCHES)+['--help','--version'],n=1,cutoff=.75)
            tip=f"a similar argument exists: '{close[0]}'" if close else f"to pass '{a}' as a value, use '-- {a}'"
            cli_fail(f"unexpected argument '{a}' found",True,tip)
        attr,label,choices=_VALUES[a]; display=a+' <'+label+'>'
        if attr not in ['includes','allows','emit','unstable'] and a in seen:
            cli_fail(f"the argument '{display}' cannot be used multiple times",True)
        seen.add(a)
        if val is None:
            if i>=len(args):val=''
            elif args[i].startswith('-') and args[i]!='-':
                aa=args[i]
                if aa in ['--help','-h']:sys.stdout.write(LONG_HELP if aa=='--help' else SHORT_HELP);raise SystemExit(0)
                cli_fail(f"unexpected argument '{aa}' found",True,f"to pass '{aa}' as a value, use '-- {aa}'")
            else:val=args[i];i+=1
        if val=='':
            msg=f"a value is required for '{display}' but none was supplied"
            if choices:msg+='\n  [possible values: '+', '.join(choices)+']'
            cli_fail(msg)
        vals=val.split(',') if attr=='emit' else [val]
        for v in vals:
            if choices and v not in choices:
                msg=f"invalid value '{v}' for '{display}'\n  [possible values: {', '.join(choices)}]"
                similar=difflib.get_close_matches(v,choices,n=1,cutoff=.8)
                if similar:msg+=f"\n\n  tip: a similar value exists: '{similar[0]}'"
                cli_fail(msg)
            if attr in ['threads','width']:
                if not re.fullmatch(r'\+?[0-9]+',v):cli_fail(f"invalid value '{v}' for '{display}': invalid digit found in string")
                if int(v)>18446744073709551615:cli_fail(f"invalid value '{v}' for '{display}': number too large to fit in target type")
                v=int(v)
            if attr in ['emit','includes','allows','unstable']:getattr(o,attr).append(v)
            else:setattr(o,attr,v)
    valid=['ui-testing','track-diagnostics','parse-yul','no-resolve-imports','ast-stats','span-visitor','print-max-storage-sizes','typeck']
    zseen=set()
    for z in o.unstable:
        if z=='help':sys.stdout.write(UNSTABLE_HELP);raise SystemExit(0)
        if z.startswith('dump'):
            if '=' not in z:cli_fail("equal sign is needed when assigning values to '-Zdump=<KIND[=PATHS...]>'",True,unstable=True)
            kind=z.split('=',2)[1]
            if kind not in ['ast','hir']:cli_fail(f"invalid value '{kind}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found",unstable=True)
        elif z not in valid:cli_fail(f"unexpected argument '-Z{z}' found",True,unstable=True)
        elif z in zseen:cli_fail(f"the argument '-Z{z}' cannot be used multiple times",True,unstable=True)
        zseen.add(z)
    return o

@dataclass
class Source:
    name: str
    text: str
    path: str=''
    items: list=field(default_factory=list)
    imports: list=field(default_factory=list)
    tokens: list=field(default_factory=list)
    def __post_init__(self):
        self.lines=self.text.splitlines() or ['']
        self.starts=[0]
        for m in re.finditer('\n',self.text):self.starts.append(m.end())
    def loc(self,p):
        p=max(0,min(p,len(self.text)))
        row=bisect.bisect_right(self.starts,p)-1
        return row+1,p-self.starts[row]+1
    def byte(self,p):return len(self.text[:p].encode('utf-8'))

@dataclass
class Span:
    src: Source
    start: int
    end: int
    def loc(self):return self.src.loc(self.start)
    def json(self):return dict(file=self.src.name,start=self.src.byte(self.start),end=self.src.byte(self.end))

@dataclass
class Diagnostic:
    message: str
    span: Span|None=None
    label: str|None=None
    level: str='error'
    code: int|None=None
    children: list=field(default_factory=list) # (level, message, optional span)
    secondary: list=field(default_factory=list) # inline (span, label)
    abstract: Span|None=None

class Diagnostics:
    def __init__(self,o):self.o=o;self.items=[];self.errors=0;self.warnings=0
    def add(self,msg,span=None,label=None,level='error',code=None,children=None,secondary=None,abstract=None):
        if level=='warning' and self.o.no_warnings:return
        d=Diagnostic(msg,span,label,level,code,children or [],secondary or [],abstract)
        self.items.append(d)
        if level=='error':self.errors+=1
        if level=='warning':self.warnings+=1
        return d
    def title(self,d):
        return d.level+(f'[{d.code}]' if d.code is not None else '')+': '+d.message
    def _snippet(self,d,child=False):
        sp=d.span
        if sp is None:return ''
        src=sp.src;line,col=src.loc(sp.start);el,ec=src.loc(sp.end)
        if ec==1 and el>line:el-=1;ec=len(src.lines[el-1])+1
        w=len(str(el));ascii_=self.o.style=='ascii'
        pre=' '*(w+1);bar='|' if ascii_ else '│'
        s=((' '*w+'--> ') if ascii_ else (pre+'╭▸ '))+f'{src.name}:{line}:{col}\n'+pre+bar+'\n'
        # The diagnostic canvas clips lengthy source lines around the highlighted range.
        multiline=el!=line
        limit=max(20,self.o.width-w-3)
        def clip(text,a,b):
            if len(text)<=limit:return text,a,b,0
            # Keep about sixty columns before the start of the annotation.
            left=max(0,a-67)
            available=limit-(2 if left else 0)
            if len(text)-left<=available:left=max(0,len(text)-available)
            right=min(len(text),left+available)
            clipped=('… ' if left else '')+text[left:right]+('…' if right<len(text) else '')
            delta=left-(2 if left else 0)
            return clipped,a-delta,b-delta,delta
        if not multiline:
            txt=src.lines[line-1] if line<=len(src.lines) else ''
            txt=txt.replace('\t','    ')
            txt,a,b,delta=clip(txt,col-1,max(col,ec-1))
            s+=str(line).rjust(w)+' '+bar+' '+txt+'\n'
            tail=bool(d.children or d.secondary or d.abstract)
            if ascii_:
                s+=pre+bar+' '+' '*max(0,a)+'^'*max(1,b-a)
                if d.label:s+=' '+d.label
                s+='\n'
            elif d.secondary and all(x[0].loc()[0]==line for x in d.secondary):
                marks=[' ']*max(b,1)
                for ss,label in d.secondary:
                    aa=ss.loc()[1]-1-delta;bb=src.loc(ss.end)[1]-1-delta
                    if aa>=0:
                        if len(marks)<bb:marks+=[' ']*(bb-len(marks))
                        marks[aa]='┬'
                        for k in range(aa+1,bb):marks[k]='─'
                for k in range(max(0,a),max(b,a+1)):
                    if k>=len(marks):marks.append('━')
                    else:marks[k]='━'
                s+=pre+bar+' '+''.join(marks).rstrip()+'\n'
                for n,(ss,label) in enumerate(d.secondary):
                    aa=max(0,ss.loc()[1]-1-delta)
                    s+=pre+bar+' '+' '*aa+'│\n'
                    s+=pre+('╰╴' if n==len(d.secondary)-1 and not d.children else bar+' ')+' '*aa+label+'\n'
            elif d.abstract:
                aa=max(0,d.abstract.loc()[1]-1-delta);bb=src.loc(d.abstract.end)[1]-1-delta
                marks=[' ']*max(b,bb)
                marks[aa]='┬'
                for k in range(aa+1,bb):marks[k]='─'
                for k in range(max(0,a),b):marks[k]='━'
                s+=pre+bar+' '+''.join(marks)+'\n'+pre+bar+' '+' '*aa+'│\n'
                s+=pre+bar+' '+' '*aa+'help: mark the contract as abstract: `abstract contract`\n'+pre+'╰╴\n'
            else:
                s+=pre+('│ ' if tail else '╰╴')+' '*max(0,a)+'━'*max(1,b-a)
                if d.label:s+=' '+d.label
                s+='\n'
                if tail and all(c[2] is not None for c in d.children):s+=pre+'╰╴\n'
        else:
            selected=list(range(line,el+1))
            if len(selected)>6:selected=selected[:3]+selected[-3:]
            for l in selected:
                txt=src.lines[l-1] if l<=len(src.lines) else ''
                if ascii_:
                    marker=' ' if l==line else '|'
                    s+=str(l).rjust(w)+' | '+marker+' '+txt+'\n'
                else:s+=str(l).rjust(w)+' │ '+('┏' if l==line else '┃')+' '+txt+'\n'
            if ascii_:s+=pre+'| |'+'_'*max(1,ec)+'^'+(' '+d.label if d.label else '')+'\n'
            else:s+=pre+('│ ' if d.children else '╰╴')+'┗'+'━'*max(1,ec-1)+'┛'+(' '+d.label if d.label else '')+'\n'
