    def render(self,d):
        title=self.title(d)
        if self.o.style=='short':
            prefix=''
            if d.span:
                l,c=d.span.loc();prefix=f'{d.span.src.name}:{l}:{c}: '
            return prefix+title+(': '+d.label if d.label else '')+'\n\n'
        s=title+'\n'+self._snippet(d)
        no_span_children=[c for c in d.children if c[2] is None]
        if no_span_children:
            w=len(str(d.span.src.loc(d.span.end)[0])) if d.span else 1
            pre=' '*(w+1)
            if self.o.style=='ascii':
                s+=pre+'|\n' if d.span else ''
                for level,msg,sp in no_span_children:s+=pre+'= '+level+': '+msg+'\n'
            else:
                s+=pre+'│\n'
                for i,(level,msg,sp) in enumerate(no_span_children):s+=pre+('╰ ' if i==len(no_span_children)-1 else '├ ')+level+': '+msg+'\n'
