    def linearize(self,c,stack=None):
        if c.linear:return c.linear
        stack=stack or []
        if any(x is c for x in stack):return []
        bases=[]
        for name,sp,args in c.bases:
            obj=self.lookup(name,None,c.span.src)
            if not isinstance(obj,Node):self.d.add(f'unresolved symbol `{name.split(".")[0]}`',sp);continue
            if obj.kind not in ['contract','interface','library']:self.d.add('expected contract',sp);continue
            if obj is c or obj in stack:
                self.d.add('linearization of inheritance graph impossible',c.name_span);continue
            b=self.linearize(obj,stack+[c])
