            candidate=next((s[0] for s in seqs if all(not any(z is s[0] for z in q[1:]) for q in seqs)),None)
            if candidate is None:
                self.d.add('linearization of inheritance graph impossible',c.name_span);break
            if all(x is not candidate for x in result):result.append(candidate)
            for s in seqs:
                if s and s[0] is candidate:s.pop(0)
