    def resolve(self):
        for c in self.contracts:self.linearize(c)
        if self.d.errors:return
        allnodes=[n for s in self.sources for n in walk_nodes(s.items)]
        # Variables and record fields precede function and event signatures.
        for n in allnodes:
            if n.kind in ['variable','field','udvt']:
                self.resolve_type(n.typ,n.contract,n.span.src)
                self.resolve_expr(n.init,n.contract,n.span.src,{})
        for n in allnodes:
            if n.kind in ['function','constructor','fallback','receive','modifier','event','error']:
                for p in n.params+n.returns:self.resolve_type(p.typ,n.contract,n.span.src)
                for mn,sp,args in n.modifiers:
