            for name,sp,args in c.bases:self.resolve_expr(args,c,c.span.src,{})
    def const_value(self,ts,ct,src,stack=None):
        if not ts:return None
        stack=stack or set()
        toks=[]
        for t in ts:
            v=t.value.replace('_','')
            if t.kind=='ident' and v not in ['true','false']:
                n=self.lookup(t.value,ct,src)
                if isinstance(n,Node) and n.init and id(n) not in stack:
                    val=self.const_value(n.init,n.contract,n.span.src,stack|{id(n)})
                    toks.append(str(val or 0))
                elif v in ['wei','seconds']:toks.append('*1')
                elif v in ['gwei','ether','minutes','hours','days','weeks']:toks.append('*'+str({'gwei':10**9,'ether':10**18,'minutes':60,'hours':3600,'days':86400,'weeks':604800}[v]))
