            v=eval(expr,{'__builtins__':{}},{})
            return int(v)
        except Exception:return 0
    def elementary(self,name):
        if name=='uint':return 'uint256'
        if name=='int':return 'int256'
        if name=='fixed':return 'fixed256x0'
        if name=='ufixed':return 'ufixed256x0'
        return name
    def describe_type(self,ty,ct=None,src=None,visited=None):
        # Returns external type, internal spelling, and tuple components.
        visited=visited or set()
        if not ty:return 'uint256','uint256',None
        if ty.kind=='elementary':
            it=self.elementary(ty.name);return ('address' if it=='address payable' else it),it,None
        if ty.kind=='array':
            abi,it,com=self.describe_type(ty.elem,ct,src,visited)
            suffix='['+('' if not ty.length else str(self.const_value(ty.length,ct,src or ty.span.src)))+']'
            return abi+suffix,it+suffix,com
        if ty.kind=='mapping':return 'mapping','mapping',None
        if ty.kind=='function':
            def typ(p):return self.describe_type(p.typ,ct,src,visited)[1]
            it='function ('+', '.join(typ(p) for p in ty.params)+')'
            if ty.mut!='nonpayable':it+=' '+ty.mut
            if ty.vis=='external':it+=' external'
            if ty.returns:it+=' returns ('+', '.join(typ(p) for p in ty.returns)+')'
            return 'function',it,None
        n=ty.resolved
        if not isinstance(n,Node):return ty.name,ty.name,None
        full=(n.contract.name+'.' if n.contract else '')+n.name
        if n.kind in ['contract','library','interface']:return 'address','contract '+n.name,None
        if n.kind=='enum':return 'uint8','enum '+full,None
        if n.kind=='udvt':return self.describe_type(n.typ,n.contract,src,visited)[0],full,None
        if n.kind=='struct':
            if id(n) in visited:return 'tuple','struct '+full,[]
            com=[self.abi_param(p,p.contract or n.contract,visited=visited|{id(n)}) for p in n.items]
            return 'tuple','struct '+full,com
