        if kind=='mapping' and ty.kind=='mapping':return True
        if kind=='internal' and ty.kind=='function' and ty.vis!='external':return True
        if ty.kind in ['array','mapping']:return self.contains(ty.elem,kind,seen)
        if ty.kind=='named' and isinstance(ty.resolved,Node) and ty.resolved.kind=='struct':
            n=ty.resolved
            if id(n) in seen:return False
            return any(self.contains(p.typ,kind,seen|{id(n)}) for p in n.items)
