    """Render the declaration-oriented lowered view used by the debug switch."""
    tables={k:[] for k in ['sources','contracts','functions','structs','enums','udvts','events','errors','variables']}
    ids={};cid={id(n):i for i,n in enumerate(c.contracts)};expr_count=0
    def index(name,i):return name+'Id('+str(i)+')'
    def sid(src):return index('Source',c.sources.index(src))
    def ct(n):return some(index('Contract',cid[id(n.contract)])) if n.contract is not None else 'None'
    def htype(t):
        base=typ(t)
        if t.kind=='elementary':return obj('Type',span=t.span,kind=tup('Elementary',base.fields['kind']))
        if t.kind=='named' and getattr(t,'resolved',None) and id(t.resolved) in ids:
            return obj('Type',span=t.span,kind=ids[id(t.resolved)])
        return base
    def addvar(n,kind,fun=None,span=None,name=None,no_contract=False):
        i=len(tables['variables']);ref=index('Variable',i);ids[id(n)]=ref
        v=obj('Variable',source=sid(n.span.src),contract='None' if no_contract else ct(n),function=some(fun),span=span or n.span,kind=kind,ty=htype(n.typ),name=some(n.name if name is None else name) if (n.name if name is None else name) else 'None',visibility=some(n.vis.capitalize() if n.vis else None),mutability=some(n.mut.capitalize() if n.mut in ['constant','immutable'] else None),data_location=some(n.loc.capitalize() if n.loc else None),override_=n.override,overrides=seq([]),indexed=n.indexed,initializer='None',getter='None')
        tables['variables'].append(v);return ref,v
    def function(n,getter=None):
        nonlocal expr_count
        i=len(tables['functions']);ref=index('Function',i)
        fi=obj('Function');tables['functions'].append(fi)
        if getter:
            varid,var=getter;params=[];rets=[]
            ty=n.typ
            if ty.kind not in ['array','mapping']:
                ri,rv=addvar(n,'FunctionReturn',ref,span=n.span,name='',no_contract=True)
                rv.fields['visibility']='None';rv.fields['mutability']='None';rv.fields['override_']=False
                rets=[ri]
            span=n.span;kind='Function';vis='External';mut='View';virtual=False;bodyspan=n.span
            ident=obj('Expr',id=index('Expr',expr_count),kind=tup('Ident',seq(['Res::Item(ItemId::'+varid+')'])),span=n.span);expr_count+=1
            body=obj('Block',span=n.span,stmts=seq([obj('Stmt',span=n.span,kind=tup('Return',some(ident)))]))
            var.fields['getter']=some(ref)
        else:
            params=[addvar(p,'FunctionParam',ref)[0] for p in n.params]
            rets=[addvar(p,'FunctionReturn',ref)[0] for p in n.returns]
            span=n.span;kind=n.kind.capitalize();vis=(n.vis or 'internal').capitalize();mut=n.mut.capitalize();virtual=n.virtual
            if mut=='Nonpayable':mut='NonPayable'
            bodyspan=getattr(n,'body_span',n.span)
            body=obj('Block',span=bodyspan,stmts=seq([])) if n.body is not None else None
        fi.fields=dict(source=sid(n.span.src),contract=ct(n),span=span,name=some(n.name or None),kind=kind,visibility=vis,state_mutability=mut,modifiers=seq([]),marked_virtual=virtual,virtual_=virtual or bool(n.contract and n.contract.kind=='interface'),override_=n.override,overrides=seq([]),parameters=seq(params),returns=seq(rets),body=some(body),body_span=bodyspan,gettee=some(getter[0]) if getter else 'None')
        return ref
    def lower(n):
        k=n.kind
        if k in ['pragma','using','import']:return []
        if k in ['contract','interface','library']:
            ref=index('Contract',cid[id(n)]);ids[id(n)]=ref
            node=obj('Contract');tables['contracts'].append(node)
            children=[];special={}
            for m in n.items:
                refs=lower(m);children+=refs
                if m.kind in ['constructor','fallback','receive'] and refs:special[m.kind]=refs[0].removeprefix('ItemId::')
            bases=[index('Contract',cid[id(b)]) for b in n.linear[1:]]
            node.fields=dict(source=sid(n.span.src),span=n.span,name=n.name,kind='AbstractContract' if n.abstract else k.capitalize(),bases=seq(bases),bases_args=seq([]),linearized_bases=seq([ref]+bases),linearized_bases_args=seq([]),ctor=some(special.get('constructor')),fallback=some(special.get('fallback')),receive=some(special.get('receive')),items=seq(children))
            return ['ItemId::'+ref]
        if k=='variable':
            ref,v=addvar(n,'State' if n.contract else 'File');out=['ItemId::'+ref]
            if n.vis=='public':out.append('ItemId::'+function(n,(ref,v)))
            return out
        if k in ['function','constructor','fallback','receive','modifier']:
            ref=function(n);ids[id(n)]=ref;return ['ItemId::'+ref]
        if k in ['event','error','struct','enum','udvt']:
            plural={'event':'events','error':'errors','struct':'structs','enum':'enums','udvt':'udvts'}[k]
            ref=index(k.capitalize(),len(tables[plural]));ids[id(n)]=ref
            val=obj(k.capitalize(),source=sid(n.span.src),contract=ct(n),span=n.span,name=n.name)
            if k=='event':val.fields['anonymous']=n.anonymous
            if k in ['event','error']:val.fields['parameters']=seq([addvar(p,k.capitalize())[0] for p in n.params])
            elif k=='struct':val.fields['fields']=seq([addvar(p,'Struct')[0] for p in n.items])
            elif k=='enum':val.fields['variants']=seq([t.value for t in n.variants])
            elif k=='udvt':val.fields['ty']=htype(n.typ)
            tables[plural].append(val);return ['ItemId::'+ref]
        return []
    for src in c.sources:
        refs=[]
        for n in src.items:refs+=lower(n)
        tables['sources'].append(obj('Source',file='Stdin' if not src.path else tup('Real',json.dumps(src.path)),imports=seq([]),items=seq(refs)))
    sys.stdout.write(debug(obj('Hir',**{k:seq(v) for k,v in tables.items()}))+'\n')
